CREATE OR REPLACE FUNCTION public.thread_phase11_selftest() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE uid uuid; a jsonb; s public.objects; c public.objects; cap public.objects; b jsonb; p jsonb; rn jsonb; checks jsonb:='[]'; ok boolean; input jsonb;
BEGIN SELECT user_id INTO uid FROM public.user_roles WHERE role='steward' ORDER BY user_id LIMIT 1; IF uid IS NULL THEN RETURN '{"passed":false,"blocker":"steward required"}'; END IF;
a:=jsonb_build_object('kind','human','id',uid,'authority_used','observe');
BEGIN
s:=public.thread_create_object(a,public._fx_payload('ValueSignal','Phase11 fixture','{"observed_condition":"claim waiting","baseline_performance":"9 days"}'));
input:=jsonb_build_object('signal_id',s.id,'title','mission','measurable_condition','wait','baseline','9 days','target','3 days','affected_population','claims','operating_boundaries','shadow','proof_required','timestamps','co_creator',uid,'builder',uid,'decision_authority','mandate','stop_conditions','breach','maximum_investment',1,'review_date',(current_date+30)::text,'value_hypothesis','less waiting');
BEGIN PERFORM public.thread_human_operation(a,'mission',input); ok:=false; EXCEPTION WHEN OTHERS THEN ok:=SQLERRM LIKE 'TWO_DISTINCT_HUMANS_REQUIRED%'; END;
checks:=checks||jsonb_build_object('name','Two different human accounts required','pass',ok);
BEGIN PERFORM public.thread_human_operation(a,'mission',input||'{"proof_required":""}'); ok:=false; EXCEPTION WHEN OTHERS THEN ok:=SQLERRM LIKE 'MISSION_BOUNDS_REQUIRED%'; END;
checks:=checks||jsonb_build_object('name','Production proof required','pass',ok);
c:=public.thread_create_object(a,public._fx_payload('ValueCell','Phase11 burst fixture','{}'));
BEGIN PERFORM public.thread_human_operation(a,'burst',jsonb_build_object('cell_id',c.id,'minutes',59,'phases',jsonb_build_array('Intent compression'))); ok:=false; EXCEPTION WHEN OTHERS THEN ok:=SQLERRM LIKE 'BURST_BOUND_60_180%'; END;
checks:=checks||jsonb_build_object('name','Burst lower bound','pass',ok);
BEGIN PERFORM public.thread_human_operation(a,'burst',jsonb_build_object('cell_id',c.id,'minutes',181,'phases',jsonb_build_array('Intent compression'))); ok:=false; EXCEPTION WHEN OTHERS THEN ok:=SQLERRM LIKE 'BURST_BOUND_60_180%'; END;
checks:=checks||jsonb_build_object('name','Burst upper bound','pass',ok);
b:=public.thread_human_operation(a,'burst',jsonb_build_object('cell_id',c.id,'minutes',180,'phases',jsonb_build_array('Intent compression')));
checks:=checks||jsonb_build_object('name','Burst connected by ledger-first edge','pass',EXISTS(SELECT 1 FROM public.edges WHERE from_id=(b->>'id')::uuid AND to_id=c.id));
BEGIN PERFORM public.thread_human_operation(a,'finish_burst',jsonb_build_object('burst_id',b->>'id','output_ids',jsonb_build_array(s.id),'rationale','not substantive')); ok:=false; EXCEPTION WHEN OTHERS THEN ok:=SQLERRM LIKE 'SUBSTANTIVE_OUTPUT_REQUIRED%'; END;
checks:=checks||jsonb_build_object('name','Signal is not substantive output','pass',ok);
cap:=public.thread_create_object(a,public._fx_payload('ComposableCapability','Phase11 probe fixture',public._p4_cap_body('Routing',ARRAY['claim'],ARRAY['route'])));
p:=public.thread_human_operation(a,'simulation',jsonb_build_object('capability_id',cap.id,'scenario','Policy exception'));
checks:=checks||jsonb_build_object('name','Probe is simulated and not executed','pass',EXISTS(SELECT 1 FROM public.objects WHERE id=(p->>'id')::uuid AND body->>'results'='not_executed' AND body->>'adapter_mode'='simulated' AND authority_level='observe'));
BEGIN PERFORM public.thread_human_operation(a,'finish_burst',jsonb_build_object('burst_id',b->>'id','output_ids',jsonb_build_array(p->>'id'),'rationale','not production')); ok:=false; EXCEPTION WHEN OTHERS THEN ok:=SQLERRM LIKE 'SUBSTANTIVE_OUTPUT_REQUIRED%'; END;
checks:=checks||jsonb_build_object('name','Simulated probe not substantive output','pass',ok);
rn:=public.thread_generate_rendition(a,jsonb_build_object('kind','conversational_walkthrough','purpose','Phase11 test','sources',jsonb_build_array(s.id),'citations',jsonb_build_array(s.id),'body',jsonb_build_object('sections',jsonb_build_array(jsonb_build_object('heading','Condition','text','claim wait','cites',jsonb_build_array(s.id)))),'generator',jsonb_build_object('model','rule-based','route','in_boundary','adapter_mode','none')));
checks:=checks||jsonb_build_object('name','Cited rendition generated','pass',rn->>'refused'='false');
BEGIN PERFORM public.thread_serve_rendition(a,(rn->>'rendition_id')::uuid,'other purpose'); ok:=false; EXCEPTION WHEN OTHERS THEN ok:=SQLERRM LIKE 'RENDITION_CONTEXT_MISMATCH%'; END;
checks:=checks||jsonb_build_object('name','Wrong purpose refused','pass',ok);
s:=public.thread_revise_object(a,s.id,s.version,'{"statement":"condition changed"}','source change test');
BEGIN PERFORM public.thread_serve_rendition(a,(rn->>'rendition_id')::uuid,'Phase11 test'); ok:=false; EXCEPTION WHEN OTHERS THEN ok:=SQLERRM LIKE 'RENDITION_STALE%'; END;
checks:=checks||jsonb_build_object('name','Changed source refuses stale guidance','pass',ok);
RAISE EXCEPTION 'PHASE11_ROLLBACK';
EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'PHASE11_ROLLBACK' THEN checks:=checks||jsonb_build_object('name','Execution','pass',false,'detail',SQLERRM); END IF; END;
RETURN jsonb_build_object('passed',NOT EXISTS(SELECT 1 FROM jsonb_array_elements(checks) x WHERE x->>'pass'<>'true'),'checks',checks,'fixtures','rollback-only','exit_gate','incomplete: signed-in and two-human flow; live evidence; AW-5 thresholds');
END $$;
REVOKE ALL ON FUNCTION public.thread_phase11_selftest() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.thread_phase11_selftest() TO service_role;
DO $$ DECLARE r jsonb; BEGIN r:=public.thread_phase11_selftest(); IF r->>'passed'<>'true' THEN RAISE EXCEPTION 'Phase11 acceptance failed: %',r; END IF; END $$;